import{_ as i,C as e,o as s,c,E as o,a5 as l}from"./chunks/framework.DOB-AMqW.js";const y=JSON.parse('{"title":"Expenzo Privacy Policy","description":"Privacy Policy for Expenzo, presented within Policy Hub.","frontmatter":{"title":"Expenzo Privacy Policy","description":"Privacy Policy for Expenzo, presented within Policy Hub."},"headers":[],"relativePath":"apps/expenzo/privacy.md","filePath":"apps/expenzo/privacy.md"}'),d={name:"apps/expenzo/privacy.md"};function p(h,a,u,m,f,g){const n=e("AppBreadcrumbs"),r=e("AppSubnav"),t=e("CopyStandaloneUrl");return s(),c("div",null,[o(n,{"app-id":"expenzo",current:"Privacy Policy"}),o(r,{"app-id":"expenzo"}),o(t,{path:"/privacy/expenzo",label:"Copy Play Store URL","copied-label":"Play Store URL copied","document-name":"Expenzo privacy policy"}),a[0]||(a[0]=l('<h1 id="privacy-policy-for-expenzo" tabindex="-1">Privacy Policy for Expenzo <a class="header-anchor" href="#privacy-policy-for-expenzo" aria-label="Permalink to &quot;Privacy Policy for Expenzo&quot;">​</a></h1><p><strong>Effective Date:</strong> August 1, 2026<br><strong>Last Updated:</strong> August 1, 2026</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Expenzo is a personal-finance dashboard developed by <strong>Anand Raja</strong>. It displays expense, income, budget, savings, wishlist, and checklist information from configured Google Sheets and a Google Apps Script service. It also keeps selected data and preferences on your device.</p><p>Expenzo has no advertising, developer-operated analytics, or general-purpose online user account.</p><h2 id="google-sheets-and-apps-script" tabindex="-1">Google Sheets and Apps Script <a class="header-anchor" href="#google-sheets-and-apps-script" aria-label="Permalink to &quot;Google Sheets and Apps Script&quot;">​</a></h2><p>Expenzo requests financial records from a configured Google Apps Script endpoint. These records can include categories and limits, income sources and amounts, budget-cycle dates, expense transactions, notes, totals, savings, shortages, and spending summaries. The request includes an app access token and selected budget-cycle start day.</p><p>Wishlist and checklist screens read configured Google Sheet tabs. Wishlist records can include item names, quantities, units, and comments. Checklist records include item names.</p><p>Google receives standard connection information such as IP address, user agent, request time, and requested resource. The relevant Google account or sheet owner controls the source records. Google&#39;s processing is governed by the <a href="https://policies.google.com/privacy" target="_blank" rel="noreferrer">Google Privacy Policy</a>.</p><h2 id="information-stored-on-your-device" tabindex="-1">Information Stored on Your Device <a class="header-anchor" href="#information-stored-on-your-device" aria-label="Permalink to &quot;Information Stored on Your Device&quot;">​</a></h2><p>Expenzo caches fetched finance data in browser localStorage for offline fallback. It also stores the chosen budget-cycle start day, theme, successful local-login state, and optional app-lock settings. General cached finance data is not encrypted.</p><p>The primary login checks a password hash locally. An optional PIN uses a salted PBKDF2-SHA-256 verifier. On supported Android devices, biometric unlock uses Android BiometricPrompt and Android Keystore. Expenzo does not receive or store biometric templates. These controls protect access to the interface; they do not encrypt the general finance cache.</p><h2 id="exports" tabindex="-1">Exports <a class="header-anchor" href="#exports" aria-label="Permalink to &quot;Exports&quot;">​</a></h2><p>You can export selected financial summaries or transactions as CSV or PDF. On Android, Expenzo passes the file to the system save or share chooser. Browser versions may download or share the file. Exported copies are readable outside Expenzo and are handled by the destination you choose.</p><h2 id="information-received-by-the-developer" tabindex="-1">Information Received by the Developer <a class="header-anchor" href="#information-received-by-the-developer" aria-label="Permalink to &quot;Information Received by the Developer&quot;">​</a></h2><p>The developer does not automatically receive local cache records, passwords, PINs, biometric data, or exported files. The owner of the configured Google Apps Script and Sheets can access data stored there and associated service logs. If you contact support, the developer receives the information you choose to send.</p><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p>Expenzo uses internet access for Google services, biometric authentication when you enable it, and system save or sharing features when you export. The reviewed app does not require location, contacts, phone, SMS, call-log, camera, or microphone permissions.</p><h2 id="retention-and-deletion" tabindex="-1">Retention and Deletion <a class="header-anchor" href="#retention-and-deletion" aria-label="Permalink to &quot;Retention and Deletion&quot;">​</a></h2><p>Local information remains until replaced, cleared through Android or browser site-storage settings, or removed when the app is uninstalled. Clearing local data does not delete source records in Google Sheets, Apps Script logs, or exported files. Delete those through the relevant Google account or sheet owner and every export destination.</p><h2 id="financial-information" tabindex="-1">Financial Information <a class="header-anchor" href="#financial-information" aria-label="Permalink to &quot;Financial Information&quot;">​</a></h2><p>Expenzo is an organizational and informational tool, not a bank, payment service, accountant, or financial adviser. Verify important figures against their authoritative records.</p><h2 id="changes-and-contact" tabindex="-1">Changes and Contact <a class="header-anchor" href="#changes-and-contact" aria-label="Permalink to &quot;Changes and Contact&quot;">​</a></h2><p>This policy may be updated when Expenzo&#39;s features or data practices change.</p><ul><li><strong>Developer:</strong> Anand Raja</li><li><strong>Email:</strong> <a href="mailto:anand.official.in@gmail.com" target="_blank" rel="noreferrer">anand.official.in@gmail.com</a></li></ul>',25))])}const b=i(d,[["render",p]]);export{y as __pageData,b as default};
